export class SecurityStandardsAdapter implements StandardSource {
  getName(): string { return 'SecurityStandardsAdapter'; }
  getStandard(): IsoStandard { return 'ISO/IEC 27001:2022'; }

  async evaluate(projectRoot: string): Promise<StandardSignal[]> {
    const signals: StandardSignal[] = [];
    // ejecutar cada check y agregar señales
    signals.push(...await checkSecrets(projectRoot));
    signals.push(...await checkGitignore(projectRoot));
    signals.push(...await checkDependencies(projectRoot));
    signals.push(...await checkAuthConfig(projectRoot));
    return signals;
  }
}
